import{_ as a,o as l,c as i,a2 as e}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"数字取证与舆情安全","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/数字取证.md","filePath":"安全方向/数字取证.md","lastUpdated":1792430298000}'),r={name:"安全方向/数字取证.md"};function d(o,t,h,n,s,c){return l(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="数字取证与舆情安全" tabindex="-1">数字取证与舆情安全 <a class="header-anchor" href="#数字取证与舆情安全" aria-label="Permalink to &quot;数字取证与舆情安全&quot;">​</a></h1><blockquote><p>校内对应「计算机取证」（第 5 学期，核心课）与「网络舆情安全技术」（主干课程）。取证是从「事件发生」到「真相还原」的技术链。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>数字取证是安全事件处置（应急响应）的收尾环节，也是司法与执法场景的核心需求；</li><li>网络舆情安全是 FAFU 专业的特色方向之一（学院有网络舆情监测系统等实验设备）；</li><li>CTF Misc 方向大量考察取证技能（文件分析、隐写、流量取证）。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/操作系统.html">文件系统 / 操作系统</a> 基础</li><li><a href="./../必学工具/抓包与流量分析.html">抓包与流量分析</a></li><li><a href="./恶意代码分析.html">恶意代码分析</a>（关联）</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>取证流程：保全 → 镜像 → 分析 → 报告（证据链意识）</li><li>磁盘与文件取证：文件系统、删除文件恢复、日志分析</li><li>内存取证（Volatility 等）</li><li>网络取证：流量还原、日志关联</li><li>隐写术与隐写分析（图片、音频、流量隐写）——CTF Misc 高频考点</li><li>网络舆情：舆情监测、内容安全、溯源（FAFU 特色课程）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《电子数据取证》/ 校内教材</td><td>教材</td><td>课程主线</td></tr><tr><td><a href="https://ctf-wiki.org/" target="_blank" rel="noreferrer">CTF-Wiki Misc 模块</a></td><td>知识库</td><td>隐写/取证知识体系</td></tr><tr><td>Volatility 官方文档（<a href="https://www.volatilityfoundation.org/" target="_blank" rel="noreferrer">volatilityfoundation.org</a>）</td><td>文档</td><td>内存取证工具手册</td></tr><tr><td>攻防世界 Misc 题区</td><td>练习</td><td>大量真题练手</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>建立「证据链」思维：取证的第一步是保全与记录，不是分析；</li><li>多刷 Misc 题：隐写（LSB、文件合并、图片属性）是性价比极高的入门练习；</li><li>校内课程设计认真做，取证报告的规范性本身就是加分项。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>计算机取证（第 5 学期，核心课）</li><li>网络舆情安全技术 / 信息内容安全（主干课程）</li></ul>',14)])])}const f=a(r,[["render",d]]);export{_ as __pageData,f as default};
